            for (var i = 0; i < rows.length; i++) {

            	var rowText = rows[i],
                    match = rowText.match(pattern);

            	//console.log('the regex match', match, pattern)

            	if (match){

            		// check if comment closed
            		var comment = match[1], // note HTML comments are stripped now
						tagName = match[3],
						restOfLine = match[4]; // rest of line after tagName

                    //console.log('the ', comment, tagName, isInsideComment)

            		if (comment){
                        isInsideComment = !comment.match(/-->$/);
					}

					else if (tagName && !isInsideComment){

                        ++index;

                        if (restOfLine.match(/mt-stuff-ignore/)){
							//console.log('Set MTIgnoreIndex', index)
                            this.aceIndexMap.MTIgnoreIndex = index;
                            this.aceIndexMap.MTIgnoreRow = i;
						}

                        els[index] = {
                            row: i
                        };

                        //console.log('we got here ', index, els[(++index)])

                        if (debug){
                            $.extend(true, els[index], {
                                tagName: tagName.toLowerCase(),
                                restOfLine: restOfLine // for debugging
                            });
                        }

					}

				}
            }

            // store ACE indexes
            this.aceIndexMap.indexes = els;

            //console.log('this.aceIndexMap', this.aceIndexMap, debug, MTF, MTF.N)

            // validate indexes match dom
            if (debug && TvrUi.iframeEditing()){

                // check arrays match
                var N = MTF.N,
                    mismatchCount = 0;

                for (i = 0; i < N.length; i++) {

                	if (i === this.aceIndexMap.MTIgnoreIndex){

                        //console.log('MTIgnoreRow, bailing as we do not expect syncing form here', i);

                		break;
					}

                    var domEl = N[i],
                        aceEl = els[i],
                        tagName = domEl.tagName.toLowerCase();

                    if (!aceEl){
                        //console.log('No ace el', i, tagName, domEl);
                    }

                    else {

                        var tagsMatch = aceEl.tagName === tagName;

                        aceEl.match = tagsMatch;

                        if (!tagsMatch){
							mismatchCount++;
                            //console.log('Mismatch', i, aceEl.tagName, tagName, els[i], domEl);
                        }
                    }


                }

                //console.log('all the rows', mismatchCount, els, MTF.N);

			}

            TvrCom.endT(arguments);

