                // track the trackViewportContainer which can be made full width by Editor Enhancer for Oxygen (class)
                // And now by Oxygen changing the inline margin-left style to 0
                // https://wordpress.org/plugins/editor-enhancer-for-oxygen/
                trackViewportContainer: function(){

                    var B = this,
                        stat = B.stat;

                    //console.log('trackViewportContainer', stat.$main, stat)

                    MTint.observeTarget(stat.$main[0], B, {

                        observerConfig: {
                            attributeFilter : ['class', 'style'] //
                        },
                        item: function(el, B, mutationRecord){

                            var styleChange = mutationRecord.attributeName === 'style',
                                doAdjust = !styleChange,
                                oldValue = mutationRecord.oldValue,
                                turnOn = !(oldValue && mutationRecord.oldValue.match(/viewport-fullscreen/));

                            if (styleChange){

                                var matchMargin = mutationRecord.oldValue.match(/margin-left:\s?(.+?);/),
                                    oldMarginLeft = matchMargin ? matchMargin[1] : undefined,
                                    newMarginLeft = mutationRecord.target.style.marginLeft;

                                if (oldMarginLeft !== newMarginLeft){
                                    doAdjust = true;
                                }

                                //console.log('compare old/new margin left change', oldMarginLeft, newMarginLeft)
                            }

                            if (doAdjust){

                                //console.log('mutationRecord trackViewportContainer', turnOn, B.doUpdatePreviewForRightPanel(), mutationRecord.oldValue, mutationRecord, el, B);

                                // adjust rulers for leftPanel
                                MTint.builderLeftPanelAdjusted('oxygen', true);

                                // adjust right panel
                                MTint.builderRightPanelAdjusted(
                                    'oxygen',
                                    B.doUpdatePreviewForRightPanel()
                                );
                            }
                        }
                    })

                },

                // track oxygen right panel, which either shows or doesn't (width not currently configurable)
                trackRightPanel: function(){

                    var B = this,
                        stat = B.stat;

                    // initial nav setup
                    /*B.rightPanel.prevSpaceUsed = B.getRightPanelWidth();
                    B.rightPanel.prevDockedRight = B.rightPanel.prevSpaceUsed > 0;*/
                    MTint.builderRightPanelAdjusted('oxygen');

                    // Signal we should respond to mutation after structure, settings, close icons are clicked
                    var descendantFilter = '.oxygen-dom-tree-button, .oxygen-close-icon, .oxygen-toolbar-button-dropdown-option';
                    stat.$oxygenUIElement
                        .on('click', descendantFilter, function(){

                            var $this = $(this),
                                settingsClicked = $this.hasClass('oxygen-toolbar-button-dropdown-option') &&
                                    $this.attr('ng-click') === 'toggleSettingsPanel()';

                            //console.log('something was clicked', B.getRightPanelWidth(), $(this))

                            if (settingsClicked) {

                                // mutation observer will run right panel adjusted function after
                                // UI view changes and CSS readings are up to date
                                B.respondToRightPanelAdjust = true;
                            }

                            else {
                                MTint.builderRightPanelAdjusted(
                                    'oxygen',
                                    B.doUpdatePreviewForRightPanel()
                                );
                            }



                        });
                    /*var descendantFilter = '.oxygen-toolbar-button-dropdown-option';
                    stat.$oxygenUIElement
                        .on('click', descendantFilter, function(){

                            // mutation observer will run right panel adjusted function after
                            // UI view changes and CSS readings are up to date
                            B.respondToRightPanelAdjust = true;

                            console.log('something was clicked', $(this))

                        });*/

                    MTint.observeTarget(stat.$rightPanel[0], B, {

                        item: function(el, B, mutationRecord){

                            var widthMatch = mutationRecord.oldValue.match(/width:(.+?);/),
                                newWidth = widthMatch ? parseInt(widthMatch[1]) : null,
                                changed = newWidth !== B.rightPanel.prevSpaceUsed;

                            if (B.respondToRightPanelAdjust && changed){
                                B.respondToRightPanelAdjust = false;

                                //console.log('Check for rightPanel change', widthMatch, B.rightPanel.prevSpaceUsed, newWidth, changed)

                                MTint.builderRightPanelAdjusted(
                                    'oxygen',
                                    B.doUpdatePreviewForRightPanel()
                                );
                            }

                            // limit which mutation events trigger adjustement
                            // if (!mutationRecord.oldValue.match(/transition-property/)){
                            /*if (changed){


                            }*/
                        }
                    })
                },
