                /* Oxygen unique */
                inUserClassList: function(str, checkType){

                    var classObject = this.BuilderController.classes[str];

                    if (!classObject || !checkType){
                        return classObject;
                    }

                    // Try to guess if it's a user custom class
                    return classObject.key ? 'o2-class' : 'user-class';
                },

                // a (near) clone of Oxygen's function that can be used when Oxygen isn't active
                sortedMediaList: function(above, isGlobal){

                    var mediaList = MTint.builder_breakpoints.oxygen,
                        size = "maxSize",
                        medias = ["default"],
                        pageWidthAdded = false,
                        width = mediaList['page-width'][size];

                    for(var media in mediaList) {

                        if (mediaList.hasOwnProperty(media)) {

                            if ( media == "default" || media == "page-width" )
                                continue;

                            if ( (parseInt(mediaList[media][size]) >= parseInt(width)) || pageWidthAdded ) {
                                medias.push(media);
                            }
                            else {
                                medias.push('page-width');
                                medias.push(media);
                                pageWidthAdded = true;
                            }
                        }
                    }

                    if (!pageWidthAdded) {
                        medias.push('page-width');
                    }

                    return medias;
                },

                // another (near) clone of Oxygen's function that can be used when Oxygen isn't active
                getMediaPreviewSize: function(name) {

                    var mediaList = MTint.builder_breakpoints.oxygen,
                        sortedMedia = this.sortedMediaList();

                    //console.log('the sortedMedia', sortedMedia)

                    for (var index in sortedMedia) {

                        if (sortedMedia.hasOwnProperty(index)) {

                            var mediaName = sortedMedia[index];

                            if (mediaName === name) {

                                name = sortedMedia[parseInt(index)+1];

                                if (name !== undefined) {
                                    return (parseInt(mediaList[name].maxSize)+1);
                                }
                                else {
                                    return 360;
                                }
                            }
                        }
                    }
                },



