                // Don't lose unsaved edits when exiting Gutenberg. Autosave rather than savePost, as it never
                // publishes or changes the post status: drafts are updated in place, while published posts get
                // an autosave revision that WP offers to restore next time. Not for the site editor (templates).
                saveBeforeExit: function(){

                    let wp = this.main,
                        editor = this.isRegular && TvrCom.checkObject(wp, ['data', 'select']) && wp.data.select('core/editor');

                    // isEditedPostAutosaveable alone is true even with no edits (when no autosave exists yet)
                    if (!editor || !editor.isEditedPostDirty() || !editor.isEditedPostAutosaveable()){
                        return Promise.resolve();
                    }

                    let autosave = Promise.resolve(wp.data.dispatch('core/editor').autosave()),
                        timeout = new Promise(resolve => setTimeout(resolve, 10000));

                    return Promise.race([autosave, timeout]).catch(err => {
                        console.error('Microthemer: autosave before exiting Gutenberg failed', err);
                    });
                },

