                track_builder_device_view_click: function(B, context){

                    function respondToDeviceChange(currentDevice, deviceMode){

                        //console.log('latestDevice', currentDevice, ' -> ', deviceMode);

                        if (deviceMode && deviceMode !== currentDevice){

                            //console.log('The device changed', currentDevice, ' -> ', deviceMode);

                            B.mainWindow.MTcurrentGutDevice = deviceMode;

                            //console.log('Run MT stuff', $button)
                            MTint.update_mt_device_view(
                                'gutenberg',
                                deviceMode
                            );

                            //
                            if (MTEblock.editorHasBlocks){

                                let MTUI = B.mainWindow.document.getElementById('mt-stuff-ignore');

                                // if moving to desktop
                                if (deviceMode === 'desktop'){

                                    // rebind targeting
                                    if (MTint.builderUnq.gutenberg.mt_frontend_setup_vars_and_init){

                                        MTint.check_integrations(B.mainWindow, MTF, true);

                                        MTint.builderUnq.gutenberg.mt_frontend_setup_vars_and_init();

                                    }

                                    //show the MT UI
                                    if (MTUI){
                                        MTUI.classList.remove('hidden-for-now');
                                    }
                                }

                                // if moving away from desktop, hide the MT UI
                                else {
                                    if (MTUI){
                                        MTUI.classList.add('hidden-for-now');
                                    }
                                }
                            }

                        }
                    }

                    let MTEblock = B.mainWindow.MTblock;

                    // reset any previous device change subscription
                    if (B.unsubscribeDeviceChange){
                        B.unsubscribeDeviceChange();
                        B.unsubscribeDeviceChange = null;
                    }

                    //console.log('track_builder_device_view_click');

                    // subscribe to Gutenberg data change
                    B.unsubscribeDeviceChange = MTEblock.subscribe({
                        name: 'deviceChange',
                        timeout: 100,
                        cb: {
                            item: function(select, dispatch){

                                const deviceMode = select('core/editor').getDeviceType().toLowerCase();
                                const currentDevice = B.mainWindow.MTcurrentGutDevice || 'desktop';
                                respondToDeviceChange(currentDevice, deviceMode);
                            }
                        }
                    });



                    //console.log('B.unsubscribeDeviceChange', B.unsubscribeDeviceChange);

                },

