                getDeviceButtonOrMode: function(deviceMode, $button, openIfShut){

                    let $buttons = this.stat.deviceToggleButtons(openIfShut),
                        map = {
                            'desktop': $buttons[0],
                            'tablet': $buttons[1],
                            'mobile': $buttons[2],
                        };

                    //console.log('getDeviceButtonOrMode', deviceMode, $buttons, $button, map)

                    // if we have a mode, return the button
                    if (deviceMode){
                        return {
                            button: map[deviceMode]
                        };
                    }

                    // if we have a button, return the mode
                    if ($button){

                        let keys = Object.keys(map),
                            deviceMode = false;

                        for (let i = 0; i < keys.length; i++) {

                            let mode = keys[i],
                                button = map[mode];

                            //console.log('compare buttons', button, $button[0])

                            if (button.isSameNode($button[0])){
                                deviceMode = mode;
                                break;
                            }
                        }

                        return {
                            deviceMode: deviceMode
                        };
                    }

                },
                responsiveMenuWasTempOpened: false,
                deviceMenuDisplayTime: 0,
                hideDeviceMenu: function(B){
                    //console.log('hideDeviceMenu', B.stat.deviceMenu())
                    B.stat.$body.addClass('microthemer-hidden');
                },
                showDeviceMenu: function(B){
                    B.stat.$body.removeClass('microthemer-hidden');
                },
