			strip_extra_from_selector: function (code) {

				var match,
					sel = Array.isArray(code) ? code : this.format_ast_selector(code);

				for (var i = 0; i < sel.length; i++) {

					match = sel[i].match(this.selector_regex.plain_selector());
					//console.log('strip match', match, this.selector_regex.plain_selector())

					if (match) {
						sel[i] = match[1];
					}
				}

				return sel.join(', ');
			},

