				sel1 = Array.isArray(sel1) ? sel1 : this.format_ast_selector(sel1);
				sel2 = Array.isArray(sel2) ? sel2 : this.format_ast_selector(sel2);

				var longestSel = (sel1.length > sel2.length) ? sel1 : sel2;

				// check comma sep parts of selector
				for (var i = 0; i < longestSel.length; i++) {

					//console.log('sel1[i], sel1[i]', sel1[i], sel2[i],  sel1[i] !== sel2[i])

					// return false if any part of the selector is different
					if (sel1[i] !== sel2[i]) {
						return false;
					}
				}

