			maybe_refresh_suggestions_html: function($input, root_cat, val){

				var $combo = TvrUi.get_related_meta('combo', $input),
					$menu = $combo.$container,
					eligible = TvrCom.isDefined(val) && TvrCom.isDomEl($menu) && $menu.is(':visible');

				// if the menu is showing and we have a valid value
				if (eligible){

					// get the current menu items into an array
					var displayingValues = [];
					$menu.find('li').each(function(){

						var $li = $(this);

						if (
							$li.hasClass('ui-menu-item')
							&& $li.attr('aria-label')
							&& $li.attr('aria-label').indexOf(TvrLang.suggestions) > -1
						){

							displayingValues.push( $li.text() )
							//console.log('the li', $li.text(), $li.attr('class'), $li[0].outerHTML);
						}

					});

					// update items if not already in menu
					if (!TvrCom.in_array(val, displayingValues)){

						// manually update combo (as normally done on focus)
						var $colorVarInput = $combo.$container.siblings('.sp-input-var'),
							$comboInput = TvrCom.isDomEl($colorVarInput) ? $colorVarInput : $input,

							// update the source associated with the combo $input
							newSource = TvrUi.resolve_combobox_source($comboInput, true),
							suggestionsHTML = [];

						// extract only the suggestions from the new source
						for (var i = 0; i < newSource.length; i++) {

							var item = newSource[i];

							if (item.category === TvrLang.suggestions){
								suggestionsHTML.push(
									$('<li aria-label="'+TvrLang.suggestions+' : '+item.value+'" class="empty ui-menu-item recent-slidein">'+item.value+'<span class="mt-combo-icon clear-single-suggestion" data-action="clear-single-suggestion" title="Clear suggestion"></span><span class="mt-combo-icon save-single-suggestion " data-action="save-single-suggestion" title="Save suggestion"></span></li>').data( "ui-autocomplete-item", item )
								);
							}
						}

						// remove the current suggestions (all because recent suggestions disappear)
						$menu.find('li.ui-menu-item[aria-label^='+TvrLang.suggestions+']').remove();

						// add new suggestions
						$menu.find('li.suggestions-category').after(suggestionsHTML);
					}

				}
			},

            // insert a new suggested val into an array, removing last if we've reached the max
            splice_sug_val: function(add, remove, key, sugType, config){

                var isItemObj,
					sugValues = TvrUi.pref.my_props.sug_values[key][sugType];

                //console.log('splicing the sug', add, remove, key, sugType, config, sugValues)

                // if adding an item
                if (add){

                    //add = add.toString();

                   isItemObj = add === Object(add);
                   
                   var addLabel = isItemObj ? add.label : add;

                    // convert any number to string for sorting purposes
					addLabel = addLabel.toString();

					if (!isItemObj){
						add = addLabel;
					}

                    // don't add Google Font... string or 'none' to recent
                    if (addLabel === TvrLang.google_font ||
                        (key === 'list_style_image' && addLabel === 'none') ||
						(key === 'background_image' && addLabel === 'none') ||
                        (key === 'url' && addLabel === 'none') ||
						(key === 'mask_image' && addLabel === 'none')
					){
                        return false;
                    }

                    // get array key by checking item, or item.value in the array
                    var arrKey = TvrCom.in_array(addLabel, sugValues, false, 'label');

                    // if value already present, remove existing before prepending at 0
                    if (arrKey !== false){

                        // if color, bail as changing order of tiles in picker is confusing
                        if ( key === 'color' ){
                            return false;
                        }

                        //console.log('We remove the existing item before inserting', sugType, arrKey, sugValues)

                        sugValues.splice(arrKey, 1);
                    }

                    // prepend new value
                    sugValues.unshift(add);

                    // determine max number of suggestions - remove last item if necessary
                    var max = MTdd.max_sug_vals(key, sugType);
                    if (sugValues.length > max){
                        sugValues.pop();
                    }

                }

                // if removing an item
                if (remove !== false){

					isItemObj = remove === Object(remove);
					
					var removeLabel = isItemObj ? remove.value : remove;

					removeLabel = removeLabel.toString();

                	var index = TvrCom.in_array(removeLabel, sugValues, false, 'label')
                    //var index = sugValues.indexOf(remove);
                    if (index !== false) {
						//console.log('before remove', $.extend(true, [], sugValues))
                        sugValues.splice(index, 1);
						//console.log('after removing index', index, $.extend(true, [], sugValues), $.extend(true, {}, config))
                    }
                }

                // redraw color palette if required
                if (config.redrawPalette){
                    TvrUi.draw_palette();
                }

                // save if required
                if (config.save){
                	//console.log('the save config', save_config, sugValues, $.extend(true, {}, sugValues))
                    var save_config = config.synced_set ? { synced_set: config.synced_set } : { specific:key };
					save_config.triggeredBy = 'splice_sug_val';
                    MTdd.save_sug_vals(save_config);
                }

            },

