            // determine max number of suggestions for a property
            max_sug_vals: function(root_key, sugType, gettingVars){

                var max;

                switch(root_key) {
                    case 'color':
                        if (sugType === 'recent'){
                            max = TvrUi.numMiniTiles;
                        } else if (sugType === 'sampled'){
                            max = TvrUi.numSiteTiles; // sampled
                        } else {
                            max = TvrUi.numSavedTiles; // saved
                        }
                        break;
                    default:
                        if (sugType === 'recent'){
                            max = TvrUi.numRecent;
                        } else if (sugType === 'sampled'){
                            max = TvrUi.numSampled;
                        } else {
                            max = TvrUi.numSug;
                        }
                }

                return max;
            },

            // save sug_vals via ajax
            save_sug_vals: function(config){

                var sendData = {},
                    updateContext;

                // refresh all props (this happens on first install)
                // and when sampling variables as this updates numerous property-specific sampled variables
                if (config.all){
                    updateContext = 'all';
                    sendData = {
                        sug_values: TvrUi.pref.my_props.sug_values,
                        sug_variables: TvrUi.pref.my_props.sug_variables
                    };
                }

                // update suggestions for synced set e.g. padding
                else if (config.synced_set){
                    updateContext = 'synced_set';
                    sendData.synced_set = {};
                    config.synced_set.each(function(i){
                        var slug = $(this).attr('rel');
                        sendData.synced_set[slug] = TvrUi.pref.my_props.sug_values[slug];
                    });
                }

                // refresh suggestions for a specific root_cat/prop
                else if (config.specific){
                    updateContext = config.specific;
                    sendData.specific = TvrUi.pref.my_props.sug_values[updateContext];
                }

                // refresh sampled variables
                if (config.getVars){
                    sendData.sug_variables = TvrUi.pref.my_props.sug_variables;
                }

                //console.log('we save the sug data', updateContext, sendData)

                // ajax save the suggestions
                MTsave.simple_ajax_request({
                    'type': 'POST',
                    'url': TvrUi.ajaxUrl+'&update_sug_values='+updateContext,
                    'sendData': MTsave.serialized_data_with_single_key( JSON.stringify(sendData)  ),
                    'plus': '',
                    'minus': ''
                });

            },

            // sort and array by frequency and remove duplicates
            sortByFrequencyAndRemoveDuplicates: function(array) {

                var frequency = {}, value;

                // compute frequencies of each value
                var arrLength = array.length;
                for(var i = 0; i < arrLength; i++) {
                    value = array[i];
                    if(value in frequency) {
                        frequency[value]++;
                    }
                    else {
                        frequency[value] = 1;
                    }
                }

                // make array from the frequency object to de-duplicate
                var uniques = [];
                for(value in frequency) {
                    if ( ! frequency.hasOwnProperty(value) ) continue; // for compat
                    uniques.push(value);
                }

                // sort the uniques array in descending order by frequency
                function compareFrequency(a, b) {
                    return frequency[b] - frequency[a];
                }

                return uniques.sort(compareFrequency);
            },


