            pending_auto_saves: function(action){

                for (var timerName in TvrUi.pendingAutoSaveConfig){

                    if (!TvrUi.pendingAutoSaveConfig.hasOwnProperty(timerName)) continue; // for compat

                    var saveConfig = TvrUi.pendingAutoSaveConfig[timerName];

                    // clear timeout (if clear or save, to ensure we don't get a double-save)
                    clearTimeout(TvrUi.timer[timerName]);

                    if (action === 'save'){

                        // async false ensures the save completes before user is allowed to continue
                        saveConfig.async = false;

                        MTsave.action_save(saveConfig);

                        //console.log('save fast tracked for', timerName)
                    }

                }

                if (action === 'clear'){
                    //TvrUi.pendingAutoSave = 0;
                    TvrUi.pendingAutoSaveConfig = {};
                }

            },

