            // save the state of an input or set of inputs and then silent save
            quick_save_data: function($scope, mtData){

                mtData = mtData || MTdd.inputs_to_data($scope);

                var  savePackage = [],
                    update = {
                        action: 'array_merge_recursive_distinct',
                        trail: [],
                        data: mtData
                    };

                MTloop.updateObjectAndSavePackage(savePackage, update);

                MTsave.silent_save('', [update]);

                //console.log('the selected should be saved', savePackage, TvrUi.uiData)

                return savePackage;
            },

            // save ui config for continuity without notifying the user
            // e.g. last_viewed_selector (savePackage) or wizard advanced config (param for preferences)
            silent_save: function(param, savePackage, channel){

                var type = "GET";

                // if we have a save package
                if (savePackage){

                    // no need to silently save if the savePackage wasn't populated
                    if (!savePackage.length){
                        return false;
                    }

                    param = '&mt_action=mt_silent_save_interface';
                    type = "POST";
                }

                //console.log('silent save_package', savePackage);

                $.MTajaxQueue({
                    url: TvrUi.ajaxUrl+param,
                    type: type,
					channel: channel || 'revisions',
                    data: {
                        savePackage: savePackage
                    }
                });

            },

            /*** ajax save settings ***/
            ajax_save_settings: function(config){ TvrCom.startT(arguments);

                //TvrCom.callStack();

                config = config ? config : {};

                var deferSave = !config.noSaveDelay,
                    propOrEditor = TvrCom.isDomEl(config.$property) || config.$fullTextarea;

                // save this for bailing if no auto-save
                config.propOrEditor = propOrEditor;

               //console.log('the save config', config);
               //console.trace();


                // log time taken for MT to convert user input to visible style update
				//TvrCom.startT('user_input_to_style_render');

                // do pre-save actions if property option config.$property has been passed in
                if (propOrEditor){

                    var $editObject,
						fullCode = false;

                    // full code editor
                    if (config.$fullTextarea){

                    	fullCode = true;

                        $editObject = config.$fullTextarea;

                        // make various adjustments and render CSS in browser instantly
                        config.settings = MTsave.full_editor_pre_save(config);
                    }

                    // GUI field or inline editor
                    else {

                        $editObject = config.$property;

                        // make various adjustments and render CSS in browser instantly
                        config.settings = MTsave.input_pre_save(config);

                        //console.log('After pre save', $editObject, $editObject.val())

                        // the inline editor text should not be saved if there was a parse error when generating AST
                        if (!config.settings){
                            return false;
                        }
                    }

                    // flag if the first settings for a folder has been added

                }
                
                // if we need to compile sass on the client side
                //console.log('we should skip?', config.settings.skipSassCompile, config.settings)
                if ( MTsave.should_do_sass_compile(config) ){
					TvrUi.mt_compile_scss(config, deferSave, propOrEditor, fullCode, $editObject);
                }

                // else we can just start the save/save timer
                else {
                    MTsave.save_or_start_timer(config, deferSave, propOrEditor, $editObject);
                }

                TvrCom.endT(arguments)
            },

            should_do_sass_compile: function(config){
                return (TvrUi.client_scss &&
                    !config.settings.skipSassCompile &&
                    MTace.ace_sync_details.mode !== 'javascript' &&
                    (config.settings.fullSCSSCompile || config.settings.preprocessor)
                )
            },

            save_or_start_timer: function(config, deferSave, propOrEditor, $editObject){

                // if the full code editor code is in a valid state where selectors can be parsed and logged, update cache
                // this means blue/green highlighting will work, even when user is part way through typing unparseable (invalid) styles
                if (config.$fullTextarea && !config.sassCompileError){
                    MTace.update_parsed_full_code_selectors(config.settings, true);
                }

				// with instant preview we can perform some tasks before saving settings in the DB
				// The CSS in already in place now. GF URL can be updated, as can comp CSS etc
                if (TvrUi.iframeEditing()){

                    // nothing to refresh if the preview hasn't loaded MT's frontend script yet
                    if (MTF){

                        // update GF URL - reload stylesheet before updating computed styles
                        if (TvrUi.update_gf_url){
                            TvrUi.update_gf_url = false;
                            //console.log('Do the google font refresh')
                            MTF.refresh_stylesheet({
                                gf: true
                            });
                        }

                        // update comp styles and perform related functions
                        else {

                            // give time for browser to repaint and update comp css
                            //console.log('we run the css refresh stuff')
                            setTimeout(MTF.post_css_refresh, 200);

                        }
                    }
                }

                else {
                    TvrUi.awaitingIframeReloadAfterSave = true;
                }

				// do we defer?
				if (deferSave){

                    var timerName;

                    // sometimes timer name will be passed in (e.g. grid control adjustment)
                    if (config.timerName){
                        timerName = config.timerName;
                    }

                    // for props, we want a flag unique to the single input/editor so new input stops restarts save timer
                    else if (propOrEditor){
                        timerName = $editObject.attr('name');
                    }

                    // for all other actions, we want to ensure unique flag by using current milliseconds
                    else {
				        timerName = new Date().getTime();
                    }

					// store flag for deleting in pendingAutoSaveConfig
					config.timerName = 'save'+timerName;

					// store save config in case user tries to leave MT before save happens (so save can be triggered)
					//TvrUi.pendingAutoSave++;
					TvrUi.pendingAutoSaveConfig[config.timerName] = config;
                    //console.log('adding pending config', TvrUi.pendingAutoSave(), config.timerName, $.extend(true, {}, TvrUi.pendingAutoSaveConfig))

					// start save timer
					TvrUi.set_defer_save_timer(config, timerName);

					//console.log('Defer the save', config, TvrUi.pendingAutoSave, TvrUi.pendingAutoSaveConfig);

				}

				// do save
				else {
                    MTsave.action_save(config);
				}

            },

