            // simple ajax request of data, currently shared by view gen css and import css file
            // *** I didn't know functions could be passed as param, and their args separately,
            // use this as template for the future - see use of unshift to prepend args too ***
            // todo general_ajax_submission() could be replaced by this at some point
            simple_ajax_request: function(config){ TvrCom.startT(arguments);

                // set args array if necessary
                if (!config.cbfArgs){
                    config.cbfArgs = [];
                }

                if (config.plus){
                    MTsave.update_prog_indicator('plus', config.plus);
                }

                var paramDiv = (config.url.indexOf('?') > -1) ? '&' : '?';

                config.url+= paramDiv+'nomtcache='+new Date().getTime();


                // if skipQueue is passed, just run the ajax request immediately rather than running through
                // Microthemer's queue system
                //var ajaxFunction = config.skipQueue ? $.ajax : $.MTajaxQueue;

				$.MTajaxQueue({
					channel: config.channel
						? config.channel
						: (config.skipQueue ? 'async' : 'queueable'),
					terminateOnCompletion: (config.terminateOnCompletion || config.skipQueue),
                    type: config.type ? config.type : "GET",
                    url: config.url,
                    data: config.sendData ? config.sendData : '',
                    dataType: config.dataType ? config.dataType : 'text', // so JS doesn't execute
                    async: config.async !== undefined ? config.async : true,
                    timeout: config.timeout ? config.timeout : TvrUi.tOut,
					cb: {
						ref: 'mod.MTsave',
						funcName: 'simple_ajax_request_success',
					},
					cb_failure: {
						ref: 'mod.MTsave',
						funcName: 'simple_ajax_request_error',
					},

					// custom callback functions
					cbFunction: config.cbFunction,
					cbfArgs: config.cbfArgs,
					plus: config.plus,
					minus: config.minus,

					/*error: function(x,e){

						if (config.minus){
							MTsave.update_prog_indicator('minus' , {
									'short': config.minus,
									'long': '<p>'+TvrUi.handle_ajax_error(x,e)+'</p>'
								},
								config.plus
							);
						}
					},

					// todo callback should run on complete, regardless of success sometimes
					// provide an option for this
					success: function(data){

						if (config.minus){
							var status = false; // config.successMinus || false;
							MTsave.update_prog_indicator('minus', status, config.plus);

						}

						// add new variable to start of args so functions calling this one can vary other args
						if (config.cbFunction){
							config.cbfArgs.unshift(data);
							config.cbFunction.apply(this, config.cbfArgs);
						}
					}*/
                });

                TvrCom.endT(arguments)
            },
			simple_ajax_request_success: function(data, config){

				//console.log('simple_ajax_request_success fired', data, config)
				//console.trace();

				if (config.minus){
					var status = false; // config.successMinus || false;
					MTsave.update_prog_indicator('minus', status, config.plus);
				}

				// add new variable to start of args so functions calling this one can vary other args
				if (config.cbFunction){
					config.cbfArgs.unshift(data.responseData);
					config.cbFunction.apply(this, config.cbfArgs);
				}
			},
			simple_ajax_request_error: function(data, config){
				if (config.minus){
					MTsave.update_prog_indicator('minus' , {
							'short': config.minus,
							'long': '<p>'+TvrUi.handle_ajax_error(data.xhrSim, data.textStatus)+'</p>'
						},
						config.plus
					);
				}
			},


