		switch_layout_classes: function(side, type, num, maxNumColumns){

			maxNumColumns = maxNumColumns || Object.keys(TvrUi.pref.layout[side].items).length;

			var base = 'mt-'+side+'-'+type+'-',
				addClass = base+num,
				removeArray = [];

			for (var i = 0; i <= maxNumColumns; i++) {
				if (i !== parseInt(num)){
					removeArray.push(base+i);
				}
			}

			//console.log('the value changed', addClass, removeArray.join(' '));

			// switch layout class on main container
			TvrUi.stat.tvr
				.removeClass(removeArray.join(' '))
				.addClass(addClass);
		},

		// update the classes for the number of columns
		set_num_columns: function(num, side){

			this.layout_config(side).num_columns = parseInt(num);

			// update
			this.adjust_preview_margin_and_save_config({
				side: side
			});

			// columns number can change, so update classes
			//MTlayout.update_dynamic_category_sidebar_classes();

			MTace.update_editor_gutter();
		},

		// update the classes for the number of columns
		set_effective_num_columns: function(side){

			var num = this.sidebar_meta(side).effective_num_columns;

			//console.log('the num cols', side, num, this.sidebar_meta(side))

			this.layout_config(side).effective_num_columns = num;

			this.switch_layout_classes(side, 'cols', num);

		},

		set_effective_top_rows: function(){

			var num = this.topbar_meta().effective_num_rows;

			this.layout_config('top').effective_num_rows = num;

			this.switch_layout_classes('top', 'rows', num, 3);

		},

		// detach the site preview
		detach_preview: function(){

			/*if (MTF){
				MTF.previewContentChanging();
			}*/

			// unload preview in main window
			// must use this stat reference as window.frames['viframe'] can refer to detached too it seems
			TvrUi.stat.iframe[0].src = "about:blank"; // TvrMT.data.dyn.placeholderURLs.current;

			// ensure preview doesn't replace MT interface (overwrites detachedPreview)
			window.name = 'MTroot';

			// open site preview in new window
			// don't set params (center_popup) otherwise refresh icon doesn't show (didn't investigate thoroughly)
			window.TvrMT.detachedWin = window.open(
				'admin.php?page=tvr-microthemer-preview-wrap.php',
				'detachedPreview'
				//'width=900,height=600,chrome=yes,centerscreen=yes'
			);

			// warn if the popup was blocked
			try {
				window.TvrMT.detachedWin.focus();
			} catch (e) {
				MTsave.update_full_logs({
					'short': TvrLang.popup_blocked,
					'long': '<p>'+TvrUi.appName+' '+TvrLang.popup_blocked_long +'</p>',
					'type' : 'warning'
				})
				//alert("Pop-up Blocker is enabled! Please add this site to your exception list.");
			}

			//console.log('detach_preview ran');

			// ensure editor fills new available space
			TvrUi.stat.inlineEditor.css('height', '');
			this.modify_active_editors({ resize: true });

			// class will be added to make current toolbar full height plus editor
			if (MTlayout.detached_window_available()){

				MTdetached.remove_window_inactive_notice();

			}

		},

		detach_preview_off: function(){

			//TvrUi.pref.detach_preview = 0;

			//console.log('detach_preview_off ran');

			/*if (MTF){
				MTF.previewContentChanging();
			}*/

			// ensure sidebars widths are applied if they need to be
			if (MTlayout.editor_showing_left()){
				this.adjust_preview_margin_and_save_config({
					side: 'left',
					skipSave: 1
				});
			}

			else if (MTlayout.horizontal_only()){
				// ensure editor height matching content
				this.modify_active_editors({
					resize: true,
					updateHeight: true
				});
			}

			if (MTlayout.detached_window_available()){
				MTdetached.deactivate_window();
			}

			// update reference to iframe doc
			TvrUi.stat.iframeDoc = window.frames['viframe'];

			// put banner over
			MTlocal.maybe_load_site_preview();

			// update the selector suggestions menu reference to point to the main window again
			MTlocal.updateSuggestionsMenuReference();


			// reload selector so editor is hidden
			//TvrUi.trigger_pg_icon_click();

		},

		// we can work with the detached window
		detached_window_available: function(checkDetachedPref){

			if (TvrMT.detachedWin && window.TvrMT.MTdetached){
				detachedWin = TvrMT.detachedWin;
				MTdetached = window.TvrMT.MTdetached;
				return !checkDetachedPref || (checkDetachedPref && TvrUi.pref.detach_preview);
			}

			return false;
		},

		// get existing detached window and update refs, or attempt to load new popup
		retrieve_or_load_detached: function(){

			// ensure preview doesn't replace MT interface (overwrites detachedPreview)
			window.name = 'MTroot';

			// see if existing detached window
			var detachedWin = window.open("", "detachedPreview"),
				openNew = true;

			// retrieve references from detached window
			if (detachedWin && detachedWin.MTdetached){

				openNew = false;

				// reset the current window as the opener
				detachedWin.opener = window;

				// refresh references
				detachedWin.MTdetached.set_vars();
				TvrUi.set_vars();
				detachedWin.MTlocal.update_TvrMT_and_other_vars(window.TvrMT);

				// update global references
				MTdetached = window.TvrMT.MTdetached;

				// retrieve frontend reference from detatched window
				MTF = window.TvrMT.MTF;

				//console.log('we have MTF, and we reset the dom signals', MTF, MTF.stat.win.closed)

				// detached may be loaded, but preview may not
				if (!MTF){
					//console.log('detached loaded, but not preview', detachedWin.MTdetached, MTdetached);
					detachedWin.MTlocal.maybe_load_site_preview();
					return;
				}

				if (MTF.stat.win.closed){
					openNew = true;
				}

				else {
					// refresh frontend's references to main window
					MTF.set_vars();

					// signal that the HTML pane needs to update again
					MTF.setDomChangedSignals(); // this must come after MTF.set_vars() else it is set on a stale reference

					// Give main window reference to frontend HTML
					MTlayout.trigger_iframe_loaded();

					// reset inspect mode (may have been left on in preview) - todo test this
					MTF.unbind_wizard_hover();
					MTF.bind_wizard_hover();
				}


				//TvrUi.feature_off(false, 'hover_inspect', {noSave:1});

				//window.TvrMT.detachedWin = detachedWin;
				//console.log('detachedWin reference updated', detachedWin, detachedWin.opener, window.TvrMT);
			}

			// attempt to load new popup
			if (openNew) {

				//console.log('Setting fresh preview');

				//TvrUi.feature_on(false, 'detach_preview'); - maybe this is better

				MTlayout.toggle_layout_view('detach_preview', 1, 'left');

				// if popup was blocked, provide user with launch option (as click will open popup)
			}
		},

		trigger_iframe_loaded: function(){
			// signal that the iframe is fully ready, and pass in html reference
			MTlayout.iframe_loaded(MTF.stat.html);
		},

		// child iframe trigger this on load
		iframe_loaded: function( $fHTML ){

			MTF = window.TvrMT.MTF;
			TvrUi.stat.fHTML = $fHTML;
			//TvrUi.stat.iframeDoc = window.frames['viframe'];

			// add grid highlighting class
			if (parseInt(TvrUi.pref.grid_highlight)){
				TvrUi.stat.fHTML.addClass('grid_highlight');
			}

			// add grid group in focus class
			if (TvrUi.pref.pg_focus === 'grid'){
				TvrUi.stat.fHTML.addClass('showGridControls');
			}

			// make MTF reference available to the detached window to so not lost if main window changes
			if (MTlayout.detached_window_available(true)){
				MTdetached.iframe_loaded();
			}

			// highlight current selector
			// highlight the selector for a second or so
			//TvrUi.briefly_highlight_selector();

		},

